∀ {GF : Iris.BundledGFunctors} [inst : GoLean.IrisCustomer.GoGS GF] {E : CoPset} {Φ : Unit → Iris.IProp GF}
  {rop : GoLean.GoCore.Machine.RhsOp} {refs : List GoLean.GoCore.Machine.TargetRef} {done : List GoLean.GoValue}
  {pending : List GoLean.GoCore.Expr} {body : GoLean.GoCore.Stmt} {env eenv : GoLean.GoCore.LocalEnv}
