  {results : List GoLean.Loc} {defers : List (GoLean.GoValue × List GoLean.GoValue)} {v : GoLean.GoValue}
  {k : GoLean.GoCore.Machine.Cont},
  ▷
      WP
        (GoLean.GoCore.Machine.Config.retV v
          (GoLean.GoCore.Machine.Cont.rhsK rop refs done pending body env
            (GoLean.GoCore.Machine.Cont.seq rest kenv
              (GoLean.GoCore.Machine.Cont.frame targets targetEnv results defers
                (GoLean.GoCore.Machine.Cont.panicResumeK [GoLean.GoCore.Machine.PanicEntry.mk v true] k))))) @
        Iris.Stuckness.NotStuck ; E {{ Φ }} ⊢
    WP
      (GoLean.GoCore.Machine.Config.evalE GoLean.GoCore.Expr.recoverCall eenv
        (GoLean.GoCore.Machine.Cont.rhsK rop refs done pending body env
          (GoLean.GoCore.Machine.Cont.seq rest kenv
            (GoLean.GoCore.Machine.Cont.frame targets targetEnv results defers
              (GoLean.GoCore.Machine.Cont.panicResumeK [GoLean.GoCore.Machine.PanicEntry.mk v false] k))))) @
      Iris.Stuckness.NotStuck ; E {{ Φ }}

